<script>
document.querySelectorAll('.filter').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('.filter').forEach(b=>b.classList.remove('active'));btn.classList.add('active');const f=btn.dataset.filter;document.querySelectorAll('.product').forEach(card=>card.classList.toggle('hidden',f!=='all'&&card.dataset.category!==f));}));
const toast=document.getElementById('toast');function notify(msg){toast.textContent=msg;toast.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>toast.classList.remove('show'),4000)}
document.querySelectorAll('[data-item]').forEach(b=>b.addEventListener('click',()=>notify('Untuk menanyakan '+b.dataset.item+', kunjungi website resmi MidnightBaker: midnightbaker.id')));
document.querySelectorAll('[data-question]').forEach(b=>b.addEventListener('click',()=>respond(b.dataset.question)));
function respond(q){const box=document.getElementById('chatbox');let answer='Untuk informasi terbaru mengenai '+q.toLowerCase()+', silakan hubungi toko melalui website resmi MidnightBaker.';if(q==='Lokasi toko')answer='Toko yang dirujuk berada di Jl. Imam Bonjol No. 40, Surabaya. Buka tautan peta pada bagian Lokasi untuk navigasi.';if(q==='Info menu')answer='Menu pada contoh ini meliputi sourdough, butter croissant, pain au chocolat, cheesecake, dan pastry. Ketersediaan dapat berubah.';if(q==='Pre-order')answer='Silakan kunjungi midnightbaker.id untuk mengecek kanal pemesanan resmi dan ketersediaan produk.';box.textContent='Anda: '+q+' — '+answer}
document.getElementById('chatForm').addEventListener('submit',e=>{e.preventDefault();const input=document.getElementById('chatText');if(input.value.trim()){respond(input.value.trim());input.value=''}});
document.getElementById('chatOpen').addEventListener('click',()=>{document.getElementById('faq').scrollIntoView({behavior:'smooth',block:'center'});const box=document.getElementById('chatbox');box.style.borderColor='#4df5ff';box.style.boxShadow='0 0 22px rgba(0,224,255,.18)';setTimeout(()=>{box.style.borderColor='';box.style.boxShadow=''},2200)});
document.getElementById('whatsapp').addEventListener('click',()=>notify('Nomor WhatsApp belum dipasang. Silakan kunjungi website resmi MidnightBaker untuk kontak terbaru.'));
</script></body></html>